#[test]
fn fixes_from_3500_match_vanilla() {
    for &(ty, from, to, input, expected) in CASES_FROM_3500 {
        assert_eq!(update(ty, from, to, input), expected, "{ty} {from} -> {to}: {input}");
    }
}

#[test]
#[should_panic(expected = "Duplicate key NBT[\"list\"] (attempted merging values NBT[\"a\"] and NBT[\"b\"])")]
fn renaming_a_display_slot_onto_an_existing_one_panics_like_vanilla() {
    update("saved_data/scoreboard", 3565, 3566, r#"{data:{DisplaySlots:{slot_0:"a",list:"b"}}}"#);
}
